CREATE TABLE reservations (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  event_id BIGINT NOT NULL,
  seat TEXT NOT NULL,
  UNIQUE (event_id, seat)
);

def reserve(db, event_id, seat):
    return db.execute(
        "INSERT INTO reservations(event_id, seat) VALUES (%s, %s) "
        "ON CONFLICT (event_id, seat) DO NOTHING RETURNING id",
        (event_id, seat),
    ).fetchone()
